@keyframes fc-final-skull-drag-right {
  from { left: 6cqh; }
  to { left: calc(100% - 93.33cqh); }
}
@keyframes fc-final-skull-drag-left {
  from { left: calc(100% - 93.33cqh); }
  to { left: 6cqh; }
}
@keyframes fc-final-skull-reach-on {
  from { transform: translateX(calc(100cqw - 64cqh)); }
  to { transform: translateX(0); }
}
@keyframes fc-final-skull-withdraw-on {
  from { transform: translateX(0); }
  to { transform: translateX(35.33cqh); }
}
@keyframes fc-final-skull-reach-off {
  from { transform: translateX(35.33cqh); }
  to { transform: translateX(0); }
}
@keyframes fc-final-skull-withdraw-off {
  from { transform: translateX(0); }
  to { transform: translateX(calc(100cqw - 64cqh)); }
}
@keyframes fc-final-skull-outline-arm {
  from, to {
    --neon-horizontal-width:100%;
    --neon-vertical-height:100%;
  }
}
@keyframes fc-final-skull-snap-active {
  from {
    --skull-switch-color:var(--flowcell-button-shade-skull-inactive,#ffffff);
    --neon-fill-width:0%;
    --neon-fill-height:0%;
    --neon-fill-left:50%;
    --neon-fill-right:50%;
    --neon-fill-top:50%;
    --neon-fill-bottom:50%;
  }
  to {
    --skull-switch-color:var(--flowcell-button-shade-skull-active,#ffffff);
    --neon-fill-width:100%;
    --neon-fill-height:100%;
    --neon-fill-left:0;
    --neon-fill-right:0;
    --neon-fill-top:0;
    --neon-fill-bottom:0;
  }
}
@keyframes fc-final-skull-snap-inactive {
  from { --skull-switch-color:var(--flowcell-button-shade-skull-active,#ffffff); }
  to { --skull-switch-color:var(--flowcell-button-shade-skull-inactive,#ffffff); }
}

